<script lang="ts">
 import TennisShadowPanel from '#lib/components/admin/TennisShadowPanel.svelte';
 import {auth} from '#lib/auth.svelte.ts';
 import {anyApi} from 'convex/server';
 let rows=$state<any[]|null>(null),allowed=$state(false),checked=$state(false),busy=$state(false),error=$state(''),source=$state(''),search=$state(''),status=$state('all');
 let learning=$state<any>(null),learningError=$state('');
 $effect(()=>{const client=auth.client;learning=null;if(!allowed||!client)return;return client.onUpdate(anyApi.learning.summary,{},r=>learning=r,()=>learningError='Training status could not load.');});
 const filtered=$derived((rows??[]).filter(row=>(status==='all'||row.mode===status)&&`${row.version} ${row.sport} ${row.league} ${row.artifact.scope??'full'}`.toLowerCase().includes(search.toLowerCase())));
 $effect(()=>{const client=auth.client;allowed=false;checked=auth.status!=='loading'&&!client;rows=null;if(!client)return;return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r.isSuperAdmin===true;checked=true;},()=>{checked=true;error='Access verification failed.';});});
 $effect(()=>{const client=auth.client;if(!allowed||!client)return;return client.onUpdate(anyApi.models.list,{},r=>{rows=r;error='';},()=>error='Model registry unavailable. Reload this workspace to retry.');});
 async function register(){if(!auth.client)return;busy=true;error='';try{await auth.client.mutation(anyApi.models.register,{artifact:JSON.parse(source)});source='';}catch(e){error=e instanceof Error?e.message:'Import failed.';}finally{busy=false;}}
 async function change(id:any,retire=false){if(!auth.client)return;busy=true;error='';try{await auth.client.mutation(retire?anyApi.models.retire:anyApi.models.shadowActivate,{id});}catch(e){error=e instanceof Error?e.message:'Update failed.';}finally{busy=false;}}
</script>
<svelte:head><title>Model registry Â· PuntersEdge</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<section class="space-y-6">
 <header class="surface p-6 sm:p-8"><p class="text-xs font-semibold uppercase tracking-widest text-model">ðŸ§® Model governance</p><h1 class="mt-3 text-3xl font-bold sm:text-5xl">Model registry</h1><p class="mt-3 max-w-2xl text-sm leading-relaxed text-haze">Manage versioned candidates and their serving state. Shadow activation updates mapped forecasts; it does not approve betting recommendations.</p></header>
