 <details class="surface p-5"><summary class="cursor-pointer py-2 font-semibold">ðŸ“¥ Import a model candidate</summary><p class="mt-3 text-sm text-haze">Provide a fitted artifact with a training cutoff, competition, scope and mapped team parameters. Imports are validated on the server.</p><label for="artifact" class="mt-5 block text-sm font-semibold">Artifact JSON</label><textarea id="artifact" bind:value={source} rows="10" class="mt-2 w-full rounded-xl border border-line bg-ink p-4 font-mono text-sm" spellcheck="false" placeholder="Paste the versioned model artifact"></textarea><button class="btn-primary mt-3" disabled={busy||!source.trim()} onclick={register}>{busy?'Processingâ€¦':'Import candidate'}</button></details>
 <section class="space-y-4"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="text-xl font-bold">Candidate inventory</h2><p class="mt-1 text-sm text-haze">{rows?`${filtered.length} matching candidates`:'Loading registryâ€¦'}</p></div><div class="flex w-full flex-wrap gap-2 sm:w-auto"><label class="flex min-w-0 flex-1 flex-col gap-1 text-xs text-haze">Search<input bind:value={search} type="search" placeholder="Version, sport or league" class="min-h-11 rounded-xl border border-line bg-deep px-3 text-sm"/></label><label class="flex flex-col gap-1 text-xs text-haze">State<select bind:value={status} class="min-h-11 rounded-xl border border-line bg-deep px-3 text-sm"><option value="all">All states</option><option value="active">Serving</option><option value="shadow">Candidate</option><option value="retired">Retired</option></select></label></div></div>
 {#if !rows}<div class="workspace-state" role="status"><h2>Loading model records</h2><p>Waiting for the protected registry subscription.</p></div>{:else}{#each filtered as row(row._id)}<article class="surface p-5 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><p class="text-xs font-semibold uppercase tracking-wider text-haze">{row.sport} Â· {row.artifact.scope??'full game'}</p><h3 class="mt-2 break-words text-lg font-bold">{row.version}</h3><p class="mt-1 text-sm text-haze">{row.league}</p></div><span class="rounded-full border border-line bg-raised px-3 py-1.5 text-xs font-semibold">{row.mode==='active'?'Serving':row.mode} Â· {row.approved?'Approved':'Unvalidated'}</span></div><dl class="mt-5 grid gap-3 border-y border-line py-4 sm:grid-cols-2"><div><dt class="text-xs text-haze">Training games</dt><dd class="mt-1 font-semibold">{row.artifact.trainingCount??'Not supplied'}</dd></div><div><dt class="text-xs text-haze">Training cutoff</dt><dd class="mt-1 break-words text-sm">{row.artifact.trainedThrough}</dd></div></dl><div class="mt-4 flex flex-wrap gap-3"><button class="btn-primary" disabled={busy||row.mode==='active'} onclick={()=>change(row._id)}>{row.mode==='active'?'Currently serving':'Use for shadow forecasts'}</button><button class="btn-ghost text-loss" disabled={busy||row.mode==='retired'} onclick={()=>change(row._id,true)}>Retire candidate</button></div></article>{:else}<div class="workspace-state"><h2>{rows.length?'No matching candidates':'No models imported yet'}</h2><p>{rows.length?'Try another search or state filter.':'Import a fitted, versioned artifact to begin prospective evaluation.'}</p></div>{/each}{/if}
